let results = $json.results || [];
let formattedText = "";
if (results.length === 0) {
  formattedText = "Không tìm thấy ngôi nhà nào phù hợp trực tiếp trong cơ sở dữ liệu.";
} else {
  results.forEach((item, idx) => {
    let meta = item.metadata || {};
    formattedText += `\nCăn nhà #${idx+1} (ID: ${meta.house_id}):\n`;
    formattedText += `- Địa chỉ: ${meta.placeName || 'N/A'}, ${meta.streetName || 'N/A'}\n`;
    formattedText += `- Giá bán: ${meta.offeringPrice || 0} tỷ VNĐ\n`;
    formattedText += `- Diện tích: ${meta.area || 0} m² (Thực tế: ${meta.actualArea || 0} m²)\n`;
    formattedText += `- Số phòng ngủ: ${meta.bedrooms || 0} | Số WC: ${meta.bathrooms || 0}\n`;
    formattedText += `- Chỗ đỗ ô tô: ${meta.hasCarParking ? 'Có' : 'Không'}\n`;
    formattedText += `- Mô tả chi tiết: ${item.unified_description || ''}\n`;
  });
}
return { 
  formatted_context: formattedText, 
  user_query: $('Webhook').first().json.body.query 
};

